+
+	Ref<ShaderGraph> graph = group->get_graph();
+	if (graph.is_null()) {
+		return false;
+	}
+
+	for (const int id : graph->get_node_ids()) {
+		Ref<VisualShaderNode> node = graph->get_node(id);
+		if (node.is_null()) {
+			continue;
+		}
+
