+void VisualShaderGroupPortsDialog::_update_dialog_for_port(int p_idx) {
+	const int port_count = _get_port_count();
+	const bool has_port = p_idx >= 0 && p_idx < port_count;
+
+	name_edit->set_visible(has_port);
+	port_type_optbtn->set_visible(has_port);
+	remove_port_btn->set_disabled(!has_port);
+	move_up_btn->set_disabled(!has_port || p_idx <= 0);
+	move_down_btn->set_disabled(!has_port || p_idx >= port_count - 1);
+
+	if (!has_port) {
+		return;
+	}
+
+	// Update the controls in the editor area of the dialog.
+	// The name is only assigned if it changed, to not reset the caret while the port is being renamed.
+	const String port_name = _get_port_name(p_idx);
+	if (name_edit->get_text() != port_name) {
+		name_edit->set_text(port_name);
+	}
+	port_type_optbtn->select(_get_port_type(p_idx));
