+void VisualShaderGroupPortsDialog::_commit_port_name() {
+	ERR_FAIL_NULL(group);
+	ERR_FAIL_NULL(vs_editor);
+
+	const int port_idx = _get_selected_port();
+	if (port_idx < 0) {
+		return;
