+	} else if (ED_IS_SHORTCUT("ui_redo", p_event)) {
+		EditorNode::get_singleton()->redo();
+		handled = true;
+	}
+
+	if (handled) {
+		_update_port_list(_get_selected_port());
+		set_input_as_handled();
+	}
